using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using Comfort.Common;
using EFT;
using SPTushonka.Common.Http;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class CommandoConsole {
 static readonly List<string> history=new(),output=new();static string input="",session="",pendingSession="",dialog="",rendered="";static int historyIndex;static Task<string[]>? pending;static Vector2 scroll;static GUIStyle? console;static bool dirty=true,focusInput,lastEnglish;
 static TerminalInput terminal=new();static int pendingCaret=-1;
 static TextEditor Editor()=>GUIUtility.GetStateObject(Il2CppInterop.Runtime.Il2CppType.Of<TextEditor>(),GUIUtility.keyboardControl).Cast<TextEditor>();
 static void ReplaceInput(string value,int caret){input=value;pendingCaret=caret;focusInput=true;}
 static int promptStart;static Font? terminalFont;
 static void InputKeys(){var ev=Event.current;if(ev.type!=EventType.KeyDown||GUI.GetNameOfFocusedControl()!="LocalCommandoInput")return;var editor=Editor();int cursor=Math.Clamp(editor.cursorIndex-promptStart,0,input.Length),selection=Math.Clamp(editor.selectIndex-promptStart,0,input.Length);if(ev.keyCode==KeyCode.Tab){var choices=terminal.Suggest(input[..cursor]);var result=terminal.Complete(input,cursor,ev.shift);if(choices.Length>1)Append(string.Join("  ",choices));ReplaceInput(result.Text,result.Cursor);ev.Use();}else if(ev.control||ev.command){if(ev.keyCode==KeyCode.A){editor.SelectAll();ev.Use();}else if(ev.keyCode==KeyCode.C){editor.Copy();ev.Use();}else if(ev.keyCode==KeyCode.X){int start=Math.Min(cursor,selection),end=Math.Max(cursor,selection);if(end>start)GUIUtility.systemCopyBuffer=input[start..end];var cut=TerminalInput.Insert(input,cursor,selection,"");ReplaceInput(cut.Text,cut.Cursor);ev.Use();}else if(ev.keyCode==KeyCode.V){var paste=TerminalInput.Insert(input,cursor,selection,GUIUtility.systemCopyBuffer??"");ReplaceInput(paste.Text,paste.Cursor);ev.Use();}else if(ev.keyCode==KeyCode.L){output.Clear();dirty=true;ReplaceInput(input,cursor);ev.Use();}}else if(ev.keyCode is KeyCode.Return or KeyCode.KeypadEnter){Submit();ev.Use();}else if(ev.keyCode is KeyCode.UpArrow or KeyCode.DownArrow){historyIndex=Math.Clamp(historyIndex+(ev.keyCode==KeyCode.UpArrow?-1:1),0,history.Count);string value=historyIndex<history.Count?history[historyIndex]:"";ReplaceInput(value,value.Length);ev.Use();}else if(ev.keyCode==KeyCode.Home){editor.cursorIndex=promptStart;if(!ev.shift)editor.selectIndex=promptStart;ev.Use();}else if(ev.keyCode==KeyCode.Backspace&&editor.cursorIndex<=promptStart&&editor.selectIndex<=promptStart){ev.Use();}else if(!char.IsControl(ev.character)&&Math.Min(editor.cursorIndex,editor.selectIndex)<promptStart){if(editor.cursorIndex!=editor.selectIndex){ReplaceInput(ev.character.ToString(),1);ev.Use();}else editor.cursorIndex=editor.selectIndex=promptStart+input.Length;}}
 static IEftSession? Session()=> (Singleton<TarkovApplication>.Instance??Singleton<AbstractApplication>.Instance?.TryCast<TarkovApplication>())?.Session;
 static string SessionKey(){if(!string.IsNullOrWhiteSpace(RequestHandler.SessionId))return RequestHandler.SessionId;var app=Singleton<TarkovApplication>.Instance??Singleton<AbstractApplication>.Instance?.TryCast<TarkovApplication>()??UnityEngine.Object.FindObjectOfType<TarkovApplication>();return app?.Session?.GetPhpSessionId()??"";}
 static async Task<string> Timed(Task<string> request){if(await Task.WhenAny(request,Task.Delay(12000))!=request)throw new TimeoutException("等待服务端超时");return await request;}
 internal static void Initialize(){Plugin.Self.Log.LogInfo("Commando HTTP session ready: "+!string.IsNullOrWhiteSpace(SessionKey()));}
 static string Dialog(){using var config=JsonDocument.Parse(File.ReadAllText(Path.Combine(BepInEx.Paths.GameRootPath,"SPT_Runtime","SPT_Data","configs","core.json")));return config.RootElement.GetProperty("features").GetProperty("chatbotFeatures").GetProperty("ids").GetProperty("commando").GetString()??throw new ArgumentException("Commando 标识未配置。");}
 static JsonElement Data(JsonElement response){if(response.TryGetProperty("err",out var error)&&error.TryGetInt32(out int code)&&code!=0)throw new InvalidOperationException(response.TryGetProperty("errmsg",out var message)?message.GetString():"SPT 拒绝了请求。");return response.TryGetProperty("data",out var data)?data:response;}
 static async Task<List<(string Id,string Text)>> Replies(string id){using var response=JsonDocument.Parse(await Timed(RequestHandler.PostJsonAsync("/client/mail/dialog/view",JsonSerializer.Serialize(new{dialogId=id,type=1,limit=100}))));var data=Data(response.RootElement);var result=new List<(string,string)>();if(data.ValueKind==JsonValueKind.Object&&data.TryGetProperty("messages",out var messages)&&messages.ValueKind==JsonValueKind.Array)foreach(var message in messages.EnumerateArray()){if(!message.TryGetProperty("uid",out var uid)||uid.GetString()!=id)continue;string text=message.TryGetProperty("text",out var body)?body.GetString()??"":"";if(message.TryGetProperty("_id",out var key))result.Add((key.GetString()??"",text));}return result;}
 static async Task<string[]> Relay(string command,string id){var previous=new HashSet<string>((await Replies(id)).Select(message=>message.Id));try{using var sent=JsonDocument.Parse(await Timed(RequestHandler.PostJsonAsync("/client/mail/msg/send",JsonSerializer.Serialize(new{dialogId=id,type=1,text=command,replyTo=""}))));Data(sent.RootElement);}catch(Exception error){return new[]{"发送结果未确认："+error.Message+"。请先查看原生对话后再决定是否重发。"};}
  for(int attempt=0;attempt<6;attempt++){if(attempt>0)await Task.Delay(500);var messages=await Replies(id);var fresh=messages.Where(message=>!previous.Contains(message.Id)).Select(message=>message.Text).ToArray();if(fresh.Length>0)return fresh;}return new[]{"命令已提交，暂未收到文字回复。请查看 Commando 原生对话或相关邮件；模组不会自动重发。"};}
 static void Append(string value){output.Add(value);if(output.Count>200)output.RemoveAt(0);dirty=true;scroll.y=float.MaxValue;}
 static void Submit(){if(pending!=null)return;if(string.IsNullOrWhiteSpace(input)){Append("请输入命令，或输入 help 查看帮助。");focusInput=true;return;}try{pendingSession=SessionKey();if(pendingSession.Length==0)throw new ArgumentException("尚未读取到登录会话，请先登录角色后重试。");dialog=Dialog();string command=input;history.Add(command);historyIndex=history.Count;Append("spt> "+command);input="";pendingCaret=0;pending=Relay(command,dialog);focusInput=true;}catch(Exception error){Append("错误："+error.Message);}}
 internal static void Draw(Rect rect){string key=SessionKey();if(key!=session){session=key;terminal=new();output.Clear();history.Clear();historyIndex=0;input="";dirty=true;Append("SPT Commando\nEnter 执行 · ↑↓ 历史 · Tab 补全 · Ctrl+C/X/V/A · Ctrl+L 清屏\n输入 help 查看命令。");ReplaceInput("",0);}if(pending?.IsCompleted==true){try{var lines=pending.GetAwaiter().GetResult();if(pendingSession==session){terminal.Learn(lines);foreach(var line in lines)Append(line);}}catch(Exception error){if(pendingSession==session)Append("请求失败："+error.Message+"；不会自动重发。");}pending=null;focusInput=true;pendingCaret=input.Length;}
  InterfaceMenu.Surface(rect,new Color(.015f,.018f,.022f,1),4);if(console==null){terminalFont=Font.CreateDynamicFontFromOSFont("Consolas",15);console=new GUIStyle(GUI.skin.textArea){richText=false,wordWrap=true,fontSize=15,font=terminalFont,padding=new RectOffset(0,0,0,0),border=new RectOffset(0,0,0,0)};console.normal.background=console.focused.background=console.hover.background=console.active.background=null;console.normal.textColor=console.focused.textColor=console.hover.textColor=console.active.textColor=new Color(.75f,.94f,.8f);}
  int previousStart=promptStart;bool focused=GUI.GetNameOfFocusedControl()=="LocalCommandoInput";int previousCursor=focused?Editor().cursorIndex:0,previousSelection=focused?Editor().selectIndex:0;InputKeys();if(dirty||lastEnglish!=I18n.English){rendered=string.Join("\n",output.Select(line=>line.StartsWith("spt> ",StringComparison.Ordinal)?line:I18n.Text(line)));dirty=false;lastEnglish=I18n.English;}string status=pending!=null?"[等待 SPT 回复]":key.Length==0?"[未登录角色]":terminal.Hint(input);status=I18n.Text(status);string prefix=rendered+"\n\n"+status+"\nspt> ";promptStart=prefix.Length;string contents=prefix+input;if(focused&&!focusInput&&previousStart!=promptStart){var preserve=Editor();preserve.text=contents;preserve.cursorIndex=previousCursor>=previousStart?promptStart+Math.Clamp(previousCursor-previousStart,0,input.Length):previousCursor;preserve.selectIndex=previousSelection>=previousStart?promptStart+Math.Clamp(previousSelection-previousStart,0,input.Length):previousSelection;}float width=Math.Max(100,rect.width-34),height=Math.Max(rect.height-20,console.CalcHeight(new GUIContent(contents+"\n"),width)+20);scroll=GUI.BeginScrollView(new Rect(rect.x+12,rect.y+10,rect.width-24,rect.height-20),scroll,new Rect(0,0,width,height));GUI.SetNextControlName("LocalCommandoInput");string edited=GUI.TextArea(new Rect(0,0,width,height),contents,console);if(edited!=contents){if(edited.StartsWith(prefix,StringComparison.Ordinal)){input=TerminalInput.Clipboard(edited[prefix.Length..]);scroll.y=float.MaxValue;}else{var restore=Editor();restore.text=contents;restore.cursorIndex=restore.selectIndex=contents.Length;}}GUI.EndScrollView();if(focusInput){GUI.FocusControl("LocalCommandoInput");var editor=Editor();editor.text=contents;int caret=pendingCaret>=0?Math.Clamp(pendingCaret,0,input.Length):input.Length;editor.cursorIndex=editor.selectIndex=promptStart+caret;pendingCaret=-1;focusInput=false;scroll.y=float.MaxValue;}
 }
 internal static void Reset(){terminal=new();pendingCaret=-1;pending=null;pendingSession=dialog="";history.Clear();output.Clear();session=input="";dirty=true;console=null;if(terminalFont!=null)UnityEngine.Object.Destroy(terminalFont);terminalFont=null;}
}
